#include <bits/stdc++.h>

using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, m;
        cin >> n >> m;

        vector<ll> a(n);
        for (ll &x : a) cin >> x;

        priority_queue<ll> pq;
        ll sum = 0, ans = LLONG_MIN;

        for (int i = 0; i < n; ++i) {
            if ((int)pq.size() == m - 1) {
                ans = max(ans, m * a[i] - sum);
            }

            pq.push(a[i]);
            sum += a[i];
            if ((int)pq.size() == m) {
                sum -= pq.top();
                pq.pop();
            }
        }

        cout << ans << '\n';
    }
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<ll> b(n);
        for (ll &x : b) cin >> x;
        sort(b.begin(), b.end());

        vector<ll> sum(n + 1);
        for (int i = n - 1; i >= 0; --i) {
            sum[i] = sum[i + 1] + b[i];
        }

        vector<ll> pref(n, 1), suff(n, 1);
        for (int i = 0; i < n - 1; ++i) {
            pref[i + 1] = pref[i] * (n - i - 1) % MOD;
        }
        for (int i = n - 2; i >= 0; --i) {
            suff[i] = suff[i + 1] * (n - i - 1) % MOD;
        }

        ll ans = 0;
        for (int i = 0; i < n - 1; ++i) {
            ll diff = sum[i + 1] - (n - i - 1) * b[i];
            ll ways = pref[i] * suff[i + 1] % MOD;
            ans = (ans + diff % MOD * ways) % MOD;
        }
        cout << ans << '\n';
    }
}

#include <bits/stdc++.h>

using namespace std;

bool hasBalancedPrefixes(const string& s) {
    array<int, 3> count{1, 0, 0};
    int remainder = 0;

    for (int i = 0; i < (int)s.size(); ++i) {
        if (s[i] == '1') {
            remainder = (remainder + (i % 2 == 0 ? 2 : 1)) % 3;
        }
        ++count[remainder];
    }

    return *max_element(count.begin(), count.end())
         - *min_element(count.begin(), count.end()) <= 1;
}

string constructString(int n) {
    if (n == 1) {
        return "1";
    }
    if (n == 2) {
        return "10";
    }

    for (int first = n / 3; first <= n / 3 + 1; ++first) {
        for (int second = 2 * n / 3; second <= 2 * n / 3 + 1; ++second) {
            for (int putLastOne = 0; putLastOne <= 1; ++putLastOne) {
                if (first >= second || (putLastOne && second >= n)) {
                    continue;
                }

                string s(n, '0');
                s[first - 1] = '1';
                s[second - 1] = '1';
                if (putLastOne) {
                    s[n - 1] = '1';
                }

                if (hasBalancedPrefixes(s)) {
                    return s;
                }
            }
        }
    }

    assert(false);
    return {};
}

